# Glossary of named things across the CIDM 6333 decks.
# Fields: term, cat, aliases (also matched when auto-linking), what, when (who/when), why (why it is in the course),
# src (where to read more), ch (textbook chapters). Course vocabulary follows Appendix D of the Course Topic Guide and the decks.
# Categories: course · harness · protocol · system · paper · bench · method · org

E = []
def g(term, cat, what, when="", why="", src="", aliases=(), ch=()):
    E.append(dict(term=term, cat=cat, what=what, when=when, why=why, src=src, aliases=list(aliases), ch=list(ch)))

# ---------------- course vocabulary ----------------
g("Evolution", "course", "An Evolution is the course's unit of progression. Each one pairs one lecture with one build and one sortie, and each adds one layer to the system. E0 is orientation. E1 through E12 add the loop, patterns, tools, MCP, the harness, context, memory, coordination, failure, evaluation, observability, and deployment, in that order. An Evolution compresses or expands to fit the time available, and the order of the layers does not change.", "", "Every deck, exercise, and flight card in the course is filed by its Evolution number.", "Course Topic Guide, Using this book", aliases=("Evolutions", "E0", "E1", "E2", "E3", "E4", "E5", "E6", "E7", "E8", "E9", "E10", "E11", "E12"), ch=(22,))
g("Sprint and Drift", "course", "Sprint and Drift is the method by which the student does the work and the instructor examines it. In the Sprint, the student produces the work with AI and logs what the AI did. In the Drift, the student defends the work without AI, to a reader who can ask why. The two terms come from naval practice, where a ship cannot move and listen at once.", "The instructor developed the method for CIDM 6330 (Software Architecture) and carried it into CIDM 6333.", "The course grades understanding from the AI log and the Drift. The artifact on its own does not show what the student can defend.", "Course Topic Guide, Chapter 22; sprintanddrift.substack.com", aliases=("Sprint", "Drift", "The Sprint", "Drifts"), ch=(22,))
g("Sortie", "course", "A sortie is one flight of one flight card in one sitting. The student runs the build against the design claim pre-registered on the card and records what came back. Sortie 7 flies Flight Card 7, and the numbering continues in the same way.", "The term is borrowed from aircraft flight test, where a sortie is one flight of one aircraft.", "The sortie is the course's unit of evidence, and a claim without a sortie is an opinion.", "Course Topic Guide, Chapter 23", aliases=("Sorties", "Sortie 1", "Sortie 7", "Sortie 8", "Sortie 9", "Sortie 10", "Sortie 11"), ch=(23,))
g("Flight card", "course", "A flight card is the plan for a sortie, written and committed before the run. It states the design claim, the envelope (center, corner, or expansion), the systems under test, the substrate, the test points, the instrumentation, the entry conditions, and the falsifiers. The flight log is the companion record of what happened when the card flew.", "Appendix A of the Course Topic Guide gives the template.", "A run counts as evidence only if the card was written before it. A card written afterward can be fitted to whatever happened.", "Course Topic Guide, Chapter 23 and Appendix A", aliases=("Flight Card", "flight cards", "Flight Card 1", "Flight Card 7", "Flight Card 8", "Flight Card 10", "FC2", "FC3", "flight log", "Flight log", "ENVELOPE", "TEST POINTS", "INSTRUMENTATION", "ENTRY CONDITIONS", "SYSTEMS UNDER TEST", "SUBSTRATE", "PRE-REGISTERED FALSIFIERS", "DESIGN CLAIM"), ch=(23,))
g("Falsifier", "course", "A falsifier is an observation, written on the flight card before the sortie, that would show the design claim to be false. The verdict after the sortie is REFUTED or NOT-REFUTED, and 'it worked' is not a verdict.", "The term comes from Karl Popper's falsificationism, applied here to engineering design claims.", "The course scores a design claim by the falsifiers it survived, because a demo can run for reasons the claim did not predict.", "Course Topic Guide, Chapter 23", aliases=("Falsifiers", "falsifiers", "REFUTED", "NOT-REFUTED"), ch=(23,))
g("Chase", "course", "The Chase is the independent observer of a sortie. A classmate takes the role and writes the verdict from the evidence alone (the ledger, the receipts, the test output), without relying on the pilot's account.", "The term comes from flight test, where a chase plane flies alongside and watches the test aircraft from outside.", "Every sortie has a Chase. The Chase writes the Go/No-Go before the sortie and the review after it, and both are committed to the repository.", "Course Topic Guide, Chapter 23", aliases=("The Chase", "Your Chase", "CHASE", "Chase review"), ch=(23,))
g("Go / No-Go", "course", "Go / No-Go is the Chase's written decision that a sortie may fly, because the entry conditions on the flight card are met, or may not. The Chase records it in the repository before the sortie.", "", "A sortie flown without a Go is unplanned, and the course does not count its result as evidence.", "Course Topic Guide, Chapter 23", aliases=("No-Go", "NO-GO", "Go/No-Go"), ch=(23,))
g("Squawk", "course", "A squawk is an anomaly recorded at the debrief after a sortie and routed to a destination: an issue, a feedback entry, an amendment to the flight card, or a re-fly.", "In aviation a squawk is a pilot's maintenance write-up.", "Without a squawk, a finding from the debrief has no record and no owner.", "Course Topic Guide, Appendix D", aliases=("squawks",), ch=(23,))
g("Design Analysis", "course", "A Design Analysis is the course's procedure for taking a system apart. It lists the nine components (perception, reasoning, planning, action, memory, tools, coordination, evaluation, governance), states the mechanism behind each, and ends with one 'why' paragraph that states the problem the design answered and what the design cost.", "Appendix B of the Course Topic Guide gives the template, and the Teardown segment of a lecture performs one live.", "The survey half of the course asks the same question of every system: why was it designed this way?", "Course Topic Guide, Chapter 24 and Appendix B", aliases=("Design Analyses", "Live Design Analysis", "Design Analysis Ledger", "nine components"), ch=(24, 2))
g("Teardown", "course", "A Teardown is the lecture segment that takes one real system apart with the Design Analysis. The subjects include FIPA and BDI, CAMEL and MetaGPT, the LangGraph supervisor, and Claude Code subagents. Each Teardown ends with the mechanism, the design choice, the cost, and the failure mode.", "", "The Teardown is the survey thread of each Evolution, the part of the lecture that examines systems other people built.", "Course Topic Guide, Chapter 24", aliases=("Teardowns",), ch=(24,))
g("Final System", "course", "The Final System is the end-of-course build. The student uses the harness assembled across the Evolutions to build an MVP tied to the E0 pitch, with verification and validation that assures the harness's actions, and a real user validates the result at the closeout.", "", "The Final System is the proof that the student's harness can build something, and it is the point the course builds toward.", "Course Topic Guide, Chapter 26; the Final System handout", aliases=("The Final System", "closeout", "closeout ceremony", "Closeout"), ch=(26,))
g("Index zero", "course", "Index zero is the human's position in the system. The human is first in priority, because the human's intent drives every decision, and final in authority, because the human signs off and the model does not. The Zero Doctrine is gzkit's statement of this position, and it is the answer to the Degradation Pattern.", "The term is gzkit's, and the E0 lecture takes it as its title.", "The gates, attestation, and the Chase all follow from it, since each one keeps a human at the point of decision.", "Course Topic Guide, Chapter 3", aliases=("index zero", "Index Zero", "Zero Doctrine"), ch=(3,))
g("Degradation Pattern", "course", "The Degradation Pattern is the slide in human review that occurs as a model keeps producing acceptable output. Careful reading becomes skimming, skimming becomes approving, and approving becomes absence. The system still runs, and nobody is answering for it. The course describes the slide under three names: cognitive surrender (the human stops judging), mediated observation (the human sees only what the model reports), and governance theater (the gates exist on paper and nothing enforces them).", "Chapter 3 of the Course Topic Guide and the E0 lecture introduce it.", "The course's governance apparatus exists to interrupt this slide.", "Course Topic Guide, Chapter 3", aliases=("Degradation", "cognitive surrender", "mediated observation", "governance theater"), ch=(3,))
g("Covenant", "course", "The covenant is gzkit's five-clause agreement between the human and the agent. It states what each may do and what each must record. Governance, in the course's sense, is this agreement plus the mechanisms that enforce it.", "", "The course's definition of governance starts from it.", "Course Topic Guide, Chapter 3", aliases=("covenant", "the covenant"), ch=(3,))
g("Five gates", "course", "The five gates are gzkit's checkpoints on a piece of work. Gate 1 is the ADR (the decision is written). Gate 2 is TDD (a test exists and was red first). Gate 3 is Docs. Gate 4 is BDD (behavioral acceptance). Gate 5 is human attestation. The Lite lane runs gates 1 and 2, and the Heavy lane runs all five.", "", "The course uses the gates to place a model's self-review: it counts at most as Gate-4 evidence and never as Gate 5 (rule GZK-GOV-007).", "Course Topic Guide, Chapter 3", aliases=("Gate", "Gates", "Gate 4", "Gate 5", "Gate-4", "Gate-5", "Lite", "Heavy", "lane", "Lane", "GZK-GOV-007"), ch=(3,))
g("Attestation", "course", "An attestation is a human's recorded judgment that a piece of work is Completed, Completed — Partial, or Dropped. It is Gate 5. A later reader can repudiate it if the record shows the work did not exist as attested.", "The term is gzkit's, and the June 2026 repudiations in the incident casebook are the worked example.", "Gate 5 is the one gate only a human can pass, so attestation is where the human answers for the work.", "Course Topic Guide, Appendix D and Appendix G", aliases=("attestation", "attestations", "Attestations", "repudiation"), ch=(3, 9))
g("Ledger", "course", "The ledger is the append-only event log that records every command, verdict, gate, and attestation with its date. It is the system's runtime truth, the L2 layer. gzkit writes it as JSONL, and the course asks the student's harness to keep one too.", "The term is gzkit's.", "'The ledger is the black box.' Anything a person or a model says about a run is a claim, and the ledger is the evidence the claim is checked against.", "Course Topic Guide, Appendix D", aliases=("ledger", "ledger.jsonl", "the ledger"), ch=(3, 12))
g("Receipt", "course", "A receipt is a schema-validated record of a command's observed result. It holds the command, its exit code, the hash of its output, and the time it ran. A claim without a receipt is not evidence.", "The term is gzkit's.", "The course uses receipts as the unit of proof in a flight log. Sortie 9's falsifier is 'a claim in the flight log with no receipt'.", "Course Topic Guide, Appendix D", aliases=("receipts", "Receipts"), ch=(18, 20))
g("Layers of truth", "course", "The layers of truth are gzkit's three classes of record. L1 is canon, the files in the repository (intent, ADRs, AGENTS.md). L2 is the ledger, the record of what happened. L3 is derived, anything a model wrote about L1 or L2 (summaries, memory). In precedence, L2 beats L1 and L1 beats L3. The file beats the memory of the file.", "gzkit ADR-0.0.9 states the doctrine.", "Figure 14 and the memory Evolution apply the precedence rule: a retrieved record is L3, so it loses to the file it describes.", "Course Topic Guide, Appendix D", aliases=("layers of truth", "L1", "L2", "L3", "canon", "CANON", "DERIVED"), ch=(15,))
g("Brief (OBPI)", "course", "A brief is gzkit's unit of human review, and OBPI stands for One Brief Per Item. A brief states the requirements, acceptance criteria, and verification for one piece of work. The requirements are numbered (REQ-1, REQ-2) so that a reviewer can cite the one a change fails.", "", "A reviewer's finding in the course has to cite what it was checked against, and the brief is where that requirement is written.", "Course Topic Guide, Appendix D", aliases=("OBPI", "brief", "briefs", "B-07"), ch=(25,))
g("ADR", "course", "An ADR is an Architecture Decision Record. It states the intent, the decision, the consequences, and the alternatives, and it is written before the code. The course's ADR-1 (E2) and ADR-2 (E7) are the student's own. gzkit's ADRs are numbered by release (ADR-0.18.0).", "Michael Nygard published the template in 2011 (title, context, decision, status, consequences). The course adds intent and alternatives, as CIDM 6330 does. The decks cite these gzkit ADRs: 0.0.2 (a standard-library CLI, argparse over click: popularity is not rationale), 0.0.9 (the state doctrine, layers of truth), 0.0.31 (the distribution invariant), 0.0.37 (AGENTS.md is rendered, not hand-edited), 0.0.54 (AGENTS.md is a map, not an encyclopedia), 0.0.71 (the first repudiated attestation), 0.0.73 (the hollow antibody), 0.0.74 (MX mode), 0.18.0 (the subagent pipeline).", "Gate 1 asks whether the ADR exists. A decision with no record cannot be defended in the Drift.", "https://cognitect.com/blog/2011/11/15/documenting-architecture-decisions", aliases=("ADRs", "ADR-1", "ADR-2", "ADR-0.18.0", "ADR-0.0.71", "ADR-0.0.74", "ADR-0.0.2", "ADR-0.0.9", "ADR-0.0.31", "ADR-0.0.37", "ADR-0.0.54", "ADR-0.0.73"), ch=(25,))
g("PRD", "course", "A PRD is a Product Requirements Document. It states what the system is for and what it must do, and the student writes it in E1 before the loop exists. Flight cards take their DESIGN CLAIM and falsifiers from it.", "", "A design claim has to come from a stated requirement, and the PRD is where the requirements are stated.", "Course Topic Guide, Chapter 25", aliases=("docs/prd.md",), ch=(25,))
g("RED witness", "course", "A RED witness is proof that a test fails without the change it covers. The test is recorded red before the code makes it green. Mutation testing is the general form of the idea, and gzkit records the witness with gz arb red.", "The idea is TDD's red-green discipline. DeMillo, Lipton & Sayward (1978) is the source for mutation testing.", "Sortie 10's design claim in E10 is that the gate fails when it should, and the RED witness is the evidence that shows it.", "Course Topic Guide, Appendix D", aliases=("RED", "red witness", "Red Witness"), ch=(19,))
g("Expansion card", "course", "An expansion card is a flight card at the edge of the envelope. It extends the design claim beyond the center case. The expected order is a center-of-envelope sortie first, then the expansion. 'Center', 'corner', and 'expansion' are the three envelope settings.", "", "The envelope setting tells the Chase how far the design claim is being pushed on this sortie.", "Course Topic Guide, Chapter 23", aliases=("expansion card", "Expansion", "envelope", "Corner of the envelope", "Center of the envelope"), ch=(23,))
g("Harness", "course", "A harness is the software that turns a model into an agent. It supplies the loop, the tools, the permissions, and the context assembly. Claude Code, Codex, and OpenCode are vendor harnesses. The files the student writes to steer one are the student's harness (Figure 17).", "'Harness engineering' is the 2025–26 term for building this layer deliberately.", "The Final System is a harness plus proof that it can build something.", "Course Topic Guide, Chapters 8, 9, 14", aliases=("harness", "harnesses", "harness engineering", "Harness engineering", "Meta-harness", "meta-harness"), ch=(8, 14))
g("V.I.B.E.S.", "course", "V.I.B.E.S. stands for Velocity Increased, Bugs Expected Software. It is gzkit's term for the failure class in which generation speed outruns verification.", "", "The term labels the failure the course's gates exist to prevent.", "Course Topic Guide, Appendix D", aliases=("VIBES", "V.I.B.E.S"))
g("Nine agent failure modes", "course", "The nine agent failure modes are gzkit's catalogue, sourced to frontier system cards. The modes are safeguard circumvention, reckless action, fabrication, skipped cheap verification, correction fails, dishonest when caught, hallucinated authorization, security shortcut, and metagaming the gate. Each has a red-team probe in Appendix C.", "", "The decks cite the modes by number (#3 fabrication, #9 metagaming), so a reader needs the catalogue to follow them.", "Course Topic Guide, Appendix C", aliases=("Appendix C", "App. C", "failure modes", "nine modes"), ch=(20,))
g("Summary laundering", "course", "Summary laundering is a human-side failure in which a model's summary of the evidence is treated as the evidence itself. In gzkit's May 2026 incident, summaries ten subagents deep became 'facts' that nobody had checked.", "The term is the course's, listed with the human-side patterns in Appendix C.", "E9's planted-falsehood lab reproduces this failure at the smallest scale.", "Course Topic Guide, Appendix C and Appendix G", aliases=("laundering",), ch=(18,))
g("HandoffResult", "course", "A HandoffResult is the typed claim a worker returns to the controller. It carries a status from a closed set (DONE, DONE_WITH_CONCERNS, NEEDS_CONTEXT, BLOCKED), the files changed, and the evidence (the test command and its exit code). The controller rejects anything that does not parse, and there is no default branch that returns DONE.", "gzkit ADR-0.18.0 is the source. The field names are the course's own.", "E8's first rule is that a worker's result is a typed claim, and this is the type.", "E8 lecture, slide 7", aliases=("DONE", "DONE_WITH_CONCERNS", "NEEDS_CONTEXT", "BLOCKED", "dispatch record", "dispatch records"), ch=(17,))
g("ReviewResult", "course", "A ReviewResult is the typed verdict a reviewer returns. It carries PASS, FAIL, or CONCERNS, findings that each cite a location (file:line, test id, diff hunk), and a list of what the reviewer checked. FAIL and CONCERNS need a finding, and the controller rejects a verdict with no citations as malformed.", "gzkit ADR-0.18.0 is the source. The field names are the course's own.", "E8's second rule is that a verdict counts only if it cites evidence and its author could not edit the code. This is the type that enforces the citation half of that rule.", "E8 lecture, slide 7", aliases=("PASS", "FAIL", "CONCERNS", "verdict", "ReviewResults"), ch=(17,))
g("Controller, worker, reviewer", "course", "Controller, worker, and reviewer are the three roles in the division of labor the course builds in E8. The controller dispatches one task. The worker (also called the implementer) returns a HandoffResult. The reviewer, which cannot edit, returns a ReviewResult. The controller merges only on PASS. The same division is plan, do, check, and it has appeared under one label or another since FIPA.", "", "The course reads the coordination-system Teardowns in terms of these three roles.", "E8 lecture; Figure 09", aliases=("controller", "worker", "reviewer", "implementer", "plan, do, check", "Plan, do, check"), ch=(17,))
g("Persona (traits, anti-traits)", "course", "A persona is a role specification the student can test. It states one job, observable traits ('cites file and line for every finding'), anti-traits ('does not rewrite the code it reviews'), and the why (what breaks if the role fails). A line such as 'You are a world-class senior engineer' is deleted on sight, because nothing in it can be tested.", "", "The anti-trait tells the model what the role must not do, and the permission deny makes the harness refuse it. The course asks for both, with the anti-trait written first.", "E8 lecture, slide 6", aliases=("persona", "personas", "anti-traits", "anti-trait"), ch=(17,))
g("Exceptional", "course", "Exceptional is the tier above a strong pass on a sortie. The flight card states an extra, harder design claim for it (two-stage review, a calibrated judge that survives injection, the removal that turns exactly the predicted cases red).", "", "It is the mark for a student who extends the design claim past what the sortie requires.", "Course Topic Guide, Chapter 23", aliases=("Exceptional mark",))
g("Route A / Route B", "course", "Route A and Route B are the two toolkit routes a student can take. Route A is a subscription harness plus a small API budget. Route B is fully local, with Ollama and open-weight models sized to the hardware. Path A and Path B in the memory Evolution are a different pair: the embedding retriever (Ollama) and the word-overlap retriever.", "", "The route sets which models and which budget the student's exercises run on.", "Course Topic Guide, Appendix F", aliases=("Route A", "Route B", "Path A", "Path B"))
g("Judgment loop", "course", "The judgment loop is the closing form, carried over from CIDM 6330, that ends chapters and Teardowns. It states the decision, the characteristics the decision privileged, the cost, the failure mode, and the preservation mechanism.", "", "It is the form in which the course asks a student to answer for a design choice.", "Course Topic Guide, Conventions", aliases=("judgment loop", "preservation mechanism", "Preservation"))
g("Tree Hollow", "course", "Tree Hollow is the Sprint and Drift essay that opens the course. Its stake is that a system can produce an answer without being able to answer for it.", "sprintanddrift.substack.com", "It is the first reading of E0.", "https://sprintanddrift.substack.com")

# ---------------- gzkit ----------------
g("gzkit", "course", "gzkit is the GovZero Kit, the course's reference design. It is a pip-installable governance toolkit with a ledger, gates, lanes, briefs, attestations, receipts, and a controller–worker pipeline. It is the one system for which the course has the entire record, including what went wrong (Appendix G, the incident casebook).", "Work on it started in January 2026. It descends from GovZero, with lineage from GitHub's spec-kit and the CLAUDE.md conventions.", "Every chapter's 'Reference design' section shows what gzkit did about that chapter's problem.", "gzkit.org; github.com/tvproductions/gzkit", aliases=("GovZero", "gz", "gz status", "gz arb red", ".gzkit"), ch=(25,))

# ---------------- harness: vendor harnesses and their parts ----------------
g("OpenCode", "harness", "OpenCode is the open-source terminal coding agent the course uses as its harness. It provides a TUI, a loop, built-in tools (read, edit, shell, webfetch), built-in agents (build, plan, general, explore, scout), permissions, skills, custom agents, commands, MCP, and plugins. AGENTS.md is its rules file.", "Anomaly (the former SST team) launched it in June 2025. It is MIT-licensed and runs with any provider or model. The repository is github.com/anomalyco/opencode.", "It is the middle ring of Figure 17, and students build their harness on it.", "https://opencode.ai/docs/", aliases=("opencode", "OpenCode Go", "OpenCode Zen", "Zen", "Go", "Big Pickle", "opencode/big-pickle", "TUI", "opencode.json"), ch=(14,))
g("Claude Code", "harness", "Claude Code is Anthropic's agentic coding tool. It is a terminal harness with tools, permissions, hooks (SessionStart, UserPromptSubmit, PreToolUse, PostToolUse, PreCompact, Stop, SessionEnd, and more), subagents in .claude/agents/, skills, and CLAUDE.md as its rules file. The Claude Agent SDK exposes the same loop to programs.", "Anthropic released it as a research preview in February 2025 and made it generally available in May 2025.", "It is the Teardown subject for subagents and hooks. The hook names on the E3 and E6 slides are Claude Code's.", "https://code.claude.com/docs", aliases=("CLAUDE.md", "Claude Agent SDK", "SessionStart", "PreToolUse", "PostToolUse", "PreCompact", "UserPromptSubmit", "SessionEnd", "Claude Code subagents", "subagent", "subagents", "Subagents"), ch=(8,))
g("Codex", "harness", "Codex is OpenAI's family of coding agents. Codex CLI is an open-source terminal agent (April 2025), and the cloud Codex agent runs tasks in sandboxes (May 2025). AGENTS.md began as Codex's rules-file convention.", "", "The course uses it as a second vendor harness for comparison, and its 'background agent' form is the survey subject of E9 through E12.", "https://openai.com/codex/", aliases=("Codex CLI", "Codex cloud", "OpenAI Agents SDK"), ch=(8, 9))
g("Cursor", "harness", "Cursor is an AI code editor (a fork of VS Code) with an agent mode, rules files in .cursor/rules, and its own background agents.", "Anysphere has developed it since 2023.", "It is one of the harnesses in the E8 and E9 feature comparisons.", "https://cursor.com", aliases=(".cursor/rules",))
g("GitHub Copilot", "harness", "GitHub Copilot is GitHub's AI pair programmer. It began as inline completion (2021), added an agent mode (February 2025), and added a cloud coding agent that works on a branch and opens pull requests (May 2025, renamed the cloud agent in April 2026).", "", "It is a vendor harness the course compares with OpenCode, Claude Code, and Codex.", "https://github.com/features/copilot", aliases=("Copilot",))
g("Gemini CLI", "harness", "Gemini CLI is Google's open-source terminal agent for Gemini models.", "Google released it in June 2025.", "It is one of the harnesses compared in the 2025 survey.", "https://github.com/google-gemini/gemini-cli")
g("AGENTS.md", "harness", "AGENTS.md is a plain Markdown file at the repository root that the harness loads into every turn. It states what the system is, what it must never do, the commands to run, and where things live. OpenCode reads it, with CLAUDE.md as a fallback. The course caps it at 4,000 characters, following gzkit ADR-0.0.54: a map, not an encyclopedia.", "It began as the Codex convention in 2025, and agents.md documents the cross-vendor format.", "It is drawer one in Figure 14. The first probe of an exercise asks whether the model answers from it.", "https://agents.md; https://opencode.ai/docs/rules/", aliases=("agents.md", "rules file", "instruction file", "instruction files"), ch=(14, 15))
g("Skills", "harness", "A skill is a folder with a SKILL.md file, which holds frontmatter (name, description) and a procedure. The harness shows the model only the name and description on each turn and loads the body when the model calls the skill tool. This arrangement is called progressive disclosure. In OpenCode, skills live in .opencode/skills/<name>/.", "Anthropic published Agent Skills in October 2025, and OpenCode supports the same layout.", "Skills are drawer three in Figure 14, and Figure 15 follows one from disk to the turn in which it runs.", "https://opencode.ai/docs/skills/; Anthropic, 'Equipping agents for the real world with Agent Skills' (2025)", aliases=("skill", "SKILL.md", "Agent Skills", "skill tool", "progressive disclosure"), ch=(14,))
g("Hooks", "harness", "A hook is code the harness runs at an event in the loop: before and after a tool call, at session start, or before compaction. Claude Code's hooks are SessionStart, PreToolUse, PostToolUse, and PreCompact. OpenCode's are plugin hooks such as tool.execute.before. A hook is a mechanism in the loop, whereas a sentence in the prompt is a request the model may ignore.", "", "E3 calls hooks 'a membrane', and E10 puts the student's first gate in one.", "https://opencode.ai/docs/plugins/; Claude Code hooks reference", aliases=("hook", "plugin", "plugins", "tool.execute.before", "membrane"), ch=(12,))
g("Permissions", "harness", "Permissions are the harness's gate on tool calls. Each tool and pattern (edit, shell, webfetch, skill, task) is set to allow, ask, or deny. In OpenCode they live in opencode.json and can be overridden per agent. A reviewer with edit: deny cannot fix the code it judges, whatever its prompt says.", "", "E3 argues that a gate has to be enforced by the harness, because a gate requested of the model in the prompt can be ignored.", "https://opencode.ai/docs/permissions/", aliases=("permission", "permission gate", "edit: deny", "ask on bash"), ch=(12,))
g("Compaction", "harness", "Compaction is what the harness does when the context window fills. The model writes a summary of the history, and the summary replaces the history. It is the middle ring's own answer to a finite window. The student did not write the summary and cannot review it before it replaces the history.", "", "E6's budget record and the handoff file exist because compaction drops whatever the model judged unimportant, and the student does not get to check that judgment.", "Anthropic, 'Effective context engineering for AI agents' (2025)", aliases=("compaction", "compacted"), ch=(15,))
g("Context window", "harness", "The context window is the text the model reads on one call: the system prompt, the rules file, the tool list, the skill index, the history, and whatever memory adds. The harness rebuilds it every turn. It has a budget, because the more tokens it holds, the less reliably the model attends to any one of them.", "", "E6 treats the window as an engineered artifact with a budget (Figure 07).", "Anthropic, 'Effective context engineering for AI agents' (2025)", aliases=("context", "window", "the window", "attention budget", "Context engineering", "context engineering"), ch=(15,))
